//! Raw bindings to DuckDB 2.0's v2 C extension API.
//!
//! `bindings.rs` is generated by `scripts/regenerate_v2_bindings.sh` from the
//! headers vendored under `vendor/`, and committed. [`init`] fetches the
//! function-pointer table from the loading DuckDB once; [`api`] hands it out.

use std::ffi::CStr;
use std::sync::OnceLock;

#[allow(
    non_camel_case_types,
    non_snake_case,
    non_upper_case_globals,
    dead_code,
    unnecessary_transmutes,
    clippy::all
)]
mod bindings;

pub use bindings::*;

/// The table version requested from `get_api`. The loader of an unstable
/// extension reads only the major version; the table matches the DuckDB
/// release the vendored headers came from.
pub const API_VERSION: &CStr = c"v2.0.0";

static TABLE: OnceLock<duckdb_ext_api_v2> = OnceLock::new();

/// Fetches the function-pointer table with `get_api` and stores it. Returns
/// `false` when `get_api` returns NULL, which means the load already failed.
///
/// # Safety
///
/// `input` must be the valid `duckdb_v2_extension_input` DuckDB passed to the
/// extension's entrypoint, and the table `get_api` returns must be a
/// `duckdb_ext_api_v2` laid out as in the vendored header.
pub unsafe fn init(input: *mut duckdb_v2_extension_input) -> bool {
    // SAFETY: the caller guarantees `input` is valid.
    let input = unsafe { &*input };
    let Some(get_api) = input.get_api else {
        return false;
    };
    // SAFETY: `get_api` is DuckDB's function, called with the extension handle
    // it gave us and a NUL-terminated version string.
    let table = unsafe { get_api(input.extension, API_VERSION.as_ptr()) };
    if table.is_null() {
        return false;
    }
    // SAFETY: a non-NULL result points at a table DuckDB keeps alive for the
    // call; we copy it, so the copy outlives that.
    let table = unsafe { *(table as *const duckdb_ext_api_v2) };
    let _ = TABLE.set(table);
    true
}

/// The stored function-pointer table.
///
/// # Panics
///
/// Panics if [`init`] has not succeeded.
pub fn api() -> &'static duckdb_ext_api_v2 {
    TABLE
        .get()
        .expect("subtoken_duckdb_sys::init was not called")
}
